/* Expense Manager dashboard — FormLogic dashboard kit grammar (plain-CSS port). */
@font-face{font-family:"Plus Jakarta Sans";font-style:normal;font-weight:200 800;font-display:swap;src:url(https://fonts.gstatic.com/s/plusjakartasans/v12/LDIoaomQNQcsA88c7O9yZ4KMCoOg4Ko20yw.woff2) format("woff2");unicode-range:U+0000-00FF,U+0131,U+0152-0153,U+02BB-02BC,U+02C6,U+02DA,U+02DC,U+0304,U+0308,U+0329,U+2000-206F,U+20AC,U+2122,U+2191,U+2193,U+2212,U+2215,U+FEFF,U+FFFD;}
:root{--ax:var(--fl-accent);}
html.fl-dark{--ax:color-mix(in srgb,var(--fl-accent) 62%,#fff);}
*{box-sizing:border-box;}
html,body{margin:0;padding:0;}
body{font-family:"Plus Jakarta Sans",ui-sans-serif,system-ui,"Segoe UI",Roboto,sans-serif;-webkit-font-smoothing:antialiased;color:var(--fl-text);background:radial-gradient(1000px 320px at 12% -100px,color-mix(in srgb,var(--fl-accent) 7%,transparent),transparent) var(--fl-bg);}
.wrap{max-width:1120px;margin:0 auto;padding:28px 24px 64px;}
.num{font-variant-numeric:tabular-nums lining-nums;}
:focus-visible{outline:2px solid var(--fl-accent);outline-offset:2px;border-radius:4px;}
.load{padding:90px 20px;text-align:center;color:var(--fl-muted);font-size:13.5px;}

/* header */
.hdr{display:flex;align-items:flex-start;justify-content:space-between;gap:16px;flex-wrap:wrap;margin-bottom:22px;}
.hdr-l{display:flex;gap:14px;min-width:0;align-items:flex-start;flex:1;}
.glyph{width:40px;height:40px;flex:none;display:grid;place-items:center;border-radius:12px;color:var(--ax);background:color-mix(in srgb,var(--fl-accent) 12%,transparent);border:1px solid color-mix(in srgb,var(--fl-accent) 22%,transparent);}
.glyph svg{width:22px;height:22px;}
.title{margin:1px 0 0;font-size:24px;line-height:1.12;font-weight:750;letter-spacing:-0.02em;color:var(--fl-text);}
.brief{margin-top:7px;font-size:13px;line-height:1.55;color:var(--fl-muted);}
.brief b{color:var(--fl-text);font-weight:650;font-variant-numeric:tabular-nums;}
.brief .dot{margin:0 7px;color:var(--fl-faint);}
.hdr-r{display:flex;gap:10px;flex:none;align-items:center;padding-top:2px;}
.btn{appearance:none;cursor:pointer;border-radius:11px;padding:10px 16px;font-weight:650;font-size:13.5px;font-family:inherit;display:inline-flex;align-items:center;gap:8px;white-space:nowrap;transition:filter .15s ease,transform .06s ease,border-color .15s ease;}
.btn:active{transform:translateY(1px);}
.btn svg{width:16px;height:16px;}
.btn-primary{border:0;background:var(--fl-accent);color:var(--fl-accent-contrast);box-shadow:0 8px 20px -10px color-mix(in srgb,var(--fl-accent) 70%,transparent);}
.btn-primary:hover{filter:brightness(1.07);}

/* KPI lede */
.kpis{display:grid;grid-template-columns:1.6fr 1fr 1fr 1fr;gap:14px;}
.kpi{background:var(--fl-surface);border:1px solid var(--fl-border);border-radius:16px;padding:16px 18px;box-shadow:var(--fl-shadow);min-width:0;display:flex;flex-direction:column;}
.kpi:not(.kpi-hero){justify-content:center;}
.kpi-label{font-size:11px;font-weight:650;letter-spacing:.07em;text-transform:uppercase;color:var(--fl-muted);}
.kpi-val{margin-top:7px;font-size:25px;font-weight:800;letter-spacing:-0.02em;line-height:1.05;color:var(--fl-text);font-variant-numeric:tabular-nums;}
.kpi-hero .kpi-val{font-size:33px;}
.kpi-sub{margin-top:5px;font-size:12px;color:var(--fl-faint);}
.kpi-sub b{color:var(--fl-muted);font-weight:650;font-variant-numeric:tabular-nums;}
.kpi-spark{margin-top:auto;padding-top:10px;}
.kpi-spark svg{display:block;width:100%;height:42px;}

/* section labels */
.sec{display:flex;align-items:center;gap:10px;margin:24px 0 12px;font-size:11px;font-weight:650;letter-spacing:.08em;text-transform:uppercase;color:var(--fl-muted);}
.sec::after{content:"";flex:1;height:1px;background:var(--fl-border);}

/* panels + grids */
.grid{display:grid;gap:14px;align-items:start;}
.g21{grid-template-columns:2fr 1fr;}
.panel{background:var(--fl-surface);border:1px solid var(--fl-border);border-radius:16px;box-shadow:var(--fl-shadow);padding:16px 18px;min-width:0;}
.panel-h{display:flex;align-items:baseline;justify-content:space-between;gap:10px;margin-bottom:10px;}
.panel-t{font-size:13.5px;font-weight:700;color:var(--fl-text);}
.panel-link{background:none;border:0;padding:0;cursor:pointer;font-family:inherit;font-size:12px;font-weight:650;color:var(--ax);}
.panel-link:hover{text-decoration:underline;}
.note{margin-top:10px;font-size:11.5px;color:var(--fl-faint);}

/* rows */
.rows{display:flex;flex-direction:column;}
.row{display:flex;align-items:center;gap:12px;padding:10px 0;border-top:1px solid var(--fl-border);}
.row:first-child{border-top:0;padding-top:2px;}
.rows .row:last-child{padding-bottom:2px;}
.row-main{min-width:0;flex:1;}
.row-title{font-size:13.5px;font-weight:600;color:var(--fl-text);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
.row-sub{margin-top:2px;font-size:12px;color:var(--fl-muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
.row-r{text-align:right;flex:none;display:flex;flex-direction:column;align-items:flex-end;gap:4px;}
.amt{font-size:13.5px;font-weight:700;color:var(--fl-text);font-variant-numeric:tabular-nums;}
.pill{display:inline-flex;align-items:center;font-size:10.5px;font-weight:700;padding:3px 9px;border-radius:999px;white-space:nowrap;}
.chip{font-size:11.5px;font-weight:650;color:var(--fl-faint);white-space:nowrap;font-variant-numeric:tabular-nums;}

/* approval queue rows */
.q-row{display:flex;align-items:center;gap:12px;padding:10px 14px;border-radius:12px;border:1px solid var(--fl-border);background:var(--fl-surface-2);margin-top:8px;position:relative;overflow:hidden;}
.q-row::before{content:"";position:absolute;left:0;top:0;bottom:0;width:3px;background:var(--q,var(--fl-accent));}

/* category bars */
.bar-row{display:grid;grid-template-columns:minmax(90px,150px) 1fr 56px;align-items:center;gap:10px;padding:5px 0;}
.bar-name{font-size:12.5px;color:var(--fl-muted);overflow:hidden;white-space:nowrap;text-overflow:ellipsis;}
.bar-track{height:8px;border-radius:5px;background:var(--fl-track);overflow:hidden;}
.bar-fill{height:100%;width:0;border-radius:5px;background:var(--fl-accent);transition:width .9s cubic-bezier(.22,1,.36,1);}
.bar-val{font-size:12.5px;font-weight:700;color:var(--fl-text);text-align:right;font-variant-numeric:tabular-nums;}

/* quick actions */
.acts{display:flex;flex-wrap:wrap;gap:10px;}
.act{display:inline-flex;align-items:center;gap:9px;background:var(--fl-surface);border:1px solid var(--fl-border);color:var(--fl-text);border-radius:12px;padding:10px 14px;cursor:pointer;font-family:inherit;font-weight:600;font-size:13px;transition:border-color .15s ease,transform .06s ease,box-shadow .15s ease;}
.act:hover{border-color:color-mix(in srgb,var(--fl-accent) 50%,transparent);box-shadow:var(--fl-shadow);}
.act:active{transform:translateY(1px);}
.act svg{width:16px;height:16px;color:var(--ax);}

/* empty states */
.empty{padding:22px 12px;text-align:center;color:var(--fl-muted);font-size:13px;line-height:1.5;}
.empty svg{width:22px;height:22px;color:var(--fl-faint);display:block;margin:0 auto 8px;}
.link-btn{background:none;border:0;padding:4px 0;color:var(--ax);cursor:pointer;font-family:inherit;font-weight:650;font-size:13px;}
.link-btn:hover{text-decoration:underline;}

/* motion */
.reveal{opacity:0;transform:translateY(10px);animation:flin .55s cubic-bezier(.22,1,.36,1) forwards;}
@keyframes flin{to{opacity:1;transform:none;}}
@media (prefers-reduced-motion:reduce){.reveal{animation:none;opacity:1;transform:none;}.bar-fill{transition:none;}}

@media (max-width:960px){.kpis{grid-template-columns:1fr 1fr;}.g21{grid-template-columns:1fr;}}
@media (max-width:600px){.wrap{padding:20px 14px 48px;}.kpi-hero{grid-column:1/-1;}.kpis .kpi:last-child:nth-child(even){grid-column:1/-1;}.hdr-r{width:100%;flex-wrap:wrap;}.hdr-r .btn{flex:1;justify-content:center;}.bar-row{grid-template-columns:minmax(76px,110px) 1fr 48px;}.title{font-size:21px;}}

// index.ts — entry point. Wires the DOM to the FormLogic app-scoped SDK.
import {
  Expense,
  StatusKey,
  StatusTotals,
  CategorySpend,
  RawRecord,
  toExpense,
  aggregate,
  categoryBreakdown,
  recentPending,
  recentClaims,
  inCurrentMonth,
  spendOf,
  weeklySpend,
  ageLabel,
  fmtShortDate,
  fmtMoney,
  fmtMoneyCompact,
  toBudgetMap,
  topCategory,
} from "./data";

interface FieldMeta {
  id: string;
  label: string;
  type: string;
}
interface FormMeta {
  formId: string;
  displayName: string;
  fields: FieldMeta[];
}
interface AppContext {
  appName: string;
  appSlug: string;
  forms: FormMeta[];
}
interface CurrentUser {
  name?: string;
  email?: string;
}
interface FormLogicSDK {
  context(): Promise<AppContext>;
  submit(formId: string, answers: Record<string, unknown>): Promise<unknown>;
  records(formId: string, opts?: { limit?: number }): Promise<RawRecord[]>;
  currentUser(): Promise<CurrentUser | null>;
  navigate(target: string): void;
  toast: { success(msg: string): void; error(msg: string): void };
  escapeHtml(value: unknown): string;
}

declare global {
  interface Window {
    FormLogic: FormLogicSDK;
  }
}

const FL = window.FormLogic;

const REDUCED_MOTION = (() => {
  try {
    return window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  } catch {
    return false;
  }
})();

// ── Inline SVG icon grammar: 24 viewBox, stroke 1.75, currentColor, no fill ──
function icon(d: string): string {
  return (
    '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" ' +
    'stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">' +
    d +
    "</svg>"
  );
}
const ICONS = {
  receipt: icon(
    '<path d="M7 3.5h10a1 1 0 0 1 1 1v16l-2.4-1.6-2.3 1.6-2.3-1.6-2.3 1.6L6 18.9V4.5a1 1 0 0 1 1-1z"/><path d="M10 8.5h5M10 12h4"/>'
  ),
  plus: icon('<path d="M12 5v14M5 12h14"/>'),
  money: icon(
    '<path d="M12 2.5v19"/><path d="M16.5 6H9.75a3.25 3.25 0 0 0 0 6.5h4.5a3.25 3.25 0 0 1 0 6.5H7"/>'
  ),
  refresh: icon('<path d="M20 12a8 8 0 1 1-2.35-5.65"/><path d="M20 4v4.3h-4.3"/>'),
  list: icon('<path d="M8.5 6h11M8.5 12h11M8.5 18h11"/><path d="M4.5 6h.01M4.5 12h.01M4.5 18h.01"/>'),
  check: icon('<path d="M4.5 12.5l4.7 4.7L19.5 6.9"/>'),
  chart: icon('<path d="M5 20v-7M11 20V6M17 20v-4"/><path d="M3 20h18"/>'),
};

const STATUS_LABEL: Record<StatusKey, string> = {
  pending: "Pending",
  approved: "Approved",
  rejected: "Rejected",
};
const STATUS_COLOR: Record<StatusKey, string> = {
  pending: "var(--fl-warn)",
  approved: "var(--fl-good)",
  rejected: "var(--fl-bad)",
};

function pill(status: StatusKey): string {
  const c = STATUS_COLOR[status];
  return (
    '<span class="pill" style="color:' +
    c +
    ";background:color-mix(in srgb, " +
    c +
    ' 15%, transparent)">' +
    STATUS_LABEL[status] +
    "</span>"
  );
}

function sparkline(vals: number[], w = 220, hh = 42): string {
  if (!vals || vals.length < 2) return "";
  let mx = 0;
  let mn = Infinity;
  for (const v of vals) {
    if (v > mx) mx = v;
    if (v < mn) mn = v;
  }
  if (mx === 0) return "";
  if (mn === mx) mn = 0;
  const rng = mx - mn || 1;
  const pts: string[] = [];
  for (let j = 0; j < vals.length; j++) {
    const x = 2 + (j / (vals.length - 1)) * (w - 4);
    const y = hh - 5 - ((vals[j] - mn) / rng) * (hh - 12);
    pts.push(x.toFixed(1) + "," + y.toFixed(1));
  }
  const line = pts.join(" ");
  return (
    '<svg viewBox="0 0 ' + w + " " + hh + '" preserveAspectRatio="none" aria-hidden="true">' +
    '<polygon points="2,' + (hh - 2) + " " + line + " " + (w - 2) + "," + (hh - 2) +
    '" fill="color-mix(in srgb, var(--fl-accent) 12%, transparent)" stroke="none"/>' +
    '<polyline points="' + line +
    '" fill="none" stroke="var(--fl-accent)" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg>'
  );
}

function sec(label: string): string {
  return '<div class="sec">' + label + "</div>";
}

function panelBlock(title: string, meta: string, body: string, navAction?: string): string {
  return (
    '<section class="panel"><div class="panel-h"><div class="panel-t">' +
    title +
    (meta ? ' <span class="chip">' + meta + "</span>" : "") +
    "</div>" +
    (navAction
      ? '<button class="panel-link" type="button" data-action="' + navAction + '">View all</button>'
      : "") +
    "</div>" +
    body +
    "</section>"
  );
}

function emptyBlock(ic: string, msg: string, action?: string, cta?: string): string {
  return (
    '<div class="empty">' +
    ic +
    FL.escapeHtml(msg) +
    (action
      ? '<div><button class="link-btn" type="button" data-action="' + action + '">' +
        FL.escapeHtml(cta || "+ Add one") +
        "</button></div>"
      : "") +
    "</div>"
  );
}

function setHeader(appName: string): void {
  const nameEl = document.getElementById("app-name");
  if (nameEl) nameEl.textContent = appName || "Expense Manager";
}

function setBody(html: string): void {
  const body = document.getElementById("body");
  if (body) body.innerHTML = html;
}

function renderShell(): string {
  return (
    '<div class="wrap">' +
    '<header class="hdr reveal"><div class="hdr-l">' +
    '<div class="glyph">' + ICONS.receipt + "</div>" +
    '<div style="min-width:0"><h1 class="title" id="app-name">Expense Manager</h1>' +
    '<div class="brief" id="brief">Loading live figures&hellip;</div></div>' +
    "</div>" +
    '<div class="hdr-r"><button class="btn btn-primary" id="top-new" type="button">' +
    ICONS.plus +
    "<span>New expense</span></button></div>" +
    "</header>" +
    '<main id="body"><div class="load">Loading dashboard&hellip;</div></main>' +
    "</div>"
  );
}

function renderError(msg: string): string {
  return '<div class="empty">' + ICONS.chart + FL.escapeHtml(msg) + "</div>";
}

// The signature Briefing line: live facts joined by dots, numbers in <b>.
function renderBriefing(expenses: Expense[], cats: CategorySpend[]): string {
  const monthSpend = spendOf(expenses.filter(inCurrentMonth));
  const pendingCount = expenses.filter((e) => e.status === "pending").length;
  const top = topCategory(cats);
  const clauses = [
    "<b>" + expenses.length.toLocaleString() + "</b> claim" + (expenses.length === 1 ? "" : "s"),
    "<b>" + fmtMoney(monthSpend) + "</b> in the last 30 days",
    "<b>" + pendingCount.toLocaleString() + "</b> awaiting approval",
  ];
  if (top) clauses.push("top category <b>" + FL.escapeHtml(top) + "</b>");
  return clauses.join('<span class="dot">&middot;</span>');
}

function kpiCard(label: string, value: string, sub: string, hero = false, spark = ""): string {
  return (
    '<div class="kpi' + (hero ? " kpi-hero" : "") + '">' +
    '<div class="kpi-label">' + label + "</div>" +
    '<div class="kpi-val">' + value + "</div>" +
    (sub ? '<div class="kpi-sub">' + sub + "</div>" : "") +
    (spark ? '<div class="kpi-spark">' + spark + "</div>" : "") +
    "</div>"
  );
}

function renderKpis(expenses: Expense[], totals: Record<StatusKey, StatusTotals>): string {
  const monthExpenses = expenses.filter(inCurrentMonth);
  const monthSpend = spendOf(monthExpenses);
  const allAmount = expenses.reduce((sum, e) => sum + e.amount, 0);
  const heroSub = expenses.length
    ? "<b>" + monthExpenses.length + "</b> claim" + (monthExpenses.length === 1 ? "" : "s") +
      " in 30 days &middot; " + fmtMoney(allAmount) + " submitted all time"
    : "No claims yet &middot; submit the first expense";
  const claims = (n: number) => "<b>" + n + "</b> claim" + (n === 1 ? "" : "s");
  return (
    '<div class="kpis">' +
    kpiCard(
      "Spend (30 days)",
      fmtMoney(monthSpend),
      heroSub,
      true,
      sparkline(weeklySpend(expenses))
    ) +
    kpiCard("Pending", fmtMoney(totals.pending.amount), claims(totals.pending.count) + " awaiting approval") +
    kpiCard("Approved", fmtMoney(totals.approved.amount), claims(totals.approved.count) + " approved") +
    kpiCard("Rejected", fmtMoney(totals.rejected.amount), claims(totals.rejected.count) + " declined") +
    "</div>"
  );
}

function renderPendingPanel(pending: Expense[], pendingCount: number): string {
  let body: string;
  if (!pending.length) {
    body = emptyBlock(
      ICONS.check,
      "All caught up — no claims are waiting for a decision.",
      "new-expense",
      "+ New expense"
    );
  } else {
    body = pending
      .map((e) => {
        const desc = FL.escapeHtml(e.description || "Untitled expense");
        const meta = [FL.escapeHtml(e.category), FL.escapeHtml(e.submittedBy || "Unknown")];
        const when = fmtShortDate(e.date || e.submittedAt);
        if (when) meta.push(when);
        const age = ageLabel(e);
        return (
          '<div class="q-row" style="--q:var(--fl-warn)"><div class="row-main">' +
          '<div class="row-title">' + desc + "</div>" +
          '<div class="row-sub">' + meta.join(" &middot; ") + "</div></div>" +
          '<div class="row-r"><span class="amt">' + fmtMoney(e.amount) + "</span>" +
          (age ? '<span class="chip">' + age + "</span>" : "") +
          "</div></div>"
        );
      })
      .join("");
  }
  const meta = pendingCount ? pendingCount + " waiting" : "";
  return panelBlock("Pending approvals", meta, body, "all-claims");
}

function renderCategoriesPanel(cats: CategorySpend[], budgets: Map<string, number>): string {
  let body: string;
  if (!cats.length) {
    body = emptyBlock(
      ICONS.chart,
      "Approved and pending spend by category will appear here.",
      "new-expense",
      "+ Add an expense"
    );
  } else {
    let max = 1;
    for (const c of cats) if (c.amount > max) max = c.amount;
    const rows = cats
      .map((c) => {
        const pct = Math.max(3, Math.round((c.amount / max) * 100));
        const limit = budgets.get(c.category);
        const over = typeof limit === "number" && c.amount > limit;
        const fill = over ? "var(--fl-warn)" : "var(--fl-accent)";
        return (
          '<div class="bar-row"><span class="bar-name" title="' + FL.escapeHtml(c.category) + '">' +
          FL.escapeHtml(c.category) +
          '</span><div class="bar-track"><div class="bar-fill" data-pct="' + pct +
          '" style="background:' + fill + '"></div></div>' +
          '<span class="bar-val">' + fmtMoneyCompact(c.amount) + "</span></div>"
        );
      })
      .join("");
    const note = budgets.size
      ? "Approved + pending &middot; amber bar = over its monthly budget"
      : "Approved + pending &middot; excludes rejected claims";
    body = rows + '<div class="note">' + note + "</div>";
  }
  return panelBlock("Spend by category", "", body);
}

function renderRecentPanel(recent: Expense[]): string {
  let body: string;
  if (!recent.length) {
    body = emptyBlock(
      ICONS.list,
      "The latest claims across every status will appear here.",
      "new-expense",
      "+ New expense"
    );
  } else {
    body =
      '<div class="rows">' +
      recent
        .map((e) => {
          const desc = FL.escapeHtml(e.description || "Untitled expense");
          const meta = [FL.escapeHtml(e.category), FL.escapeHtml(e.submittedBy || "Unknown")];
          const when = fmtShortDate(e.date || e.submittedAt);
          if (when) meta.push(when);
          return (
            '<div class="row"><div class="row-main">' +
            '<div class="row-title">' + desc + "</div>" +
            '<div class="row-sub">' + meta.join(" &middot; ") + "</div></div>" +
            '<div class="row-r"><span class="amt">' + fmtMoney(e.amount) + "</span>" +
            pill(e.status) +
            "</div></div>"
          );
        })
        .join("") +
      "</div>";
  }
  return panelBlock("Recent claims", "", body, "all-claims");
}

function renderActions(hasBudget: boolean): string {
  const items: Array<{ action: string; ic: string; label: string }> = [
    { action: "new-expense", ic: ICONS.plus, label: "New expense" },
  ];
  if (hasBudget) items.push({ action: "budgets", ic: ICONS.money, label: "Manage budgets" });
  items.push({ action: "all-claims", ic: ICONS.list, label: "All claims" });
  items.push({ action: "refresh", ic: ICONS.refresh, label: "Refresh" });
  const buttons = items
    .map(
      (it) =>
        '<button class="act" type="button" data-action="' + it.action + '">' +
        it.ic +
        "<span>" + it.label + "</span></button>"
    )
    .join("");
  return sec("Quick actions") + '<div class="acts">' + buttons + "</div>";
}

function renderDashboard(expenses: Expense[], hasBudget: boolean, budgets: Map<string, number>): string {
  const totals = aggregate(expenses);
  const cats = categoryBreakdown(expenses);
  const pendingAll = expenses.filter((e) => e.status === "pending");
  return (
    renderKpis(expenses, totals) +
    sec("Approvals &amp; spend") +
    '<div class="grid g21">' +
    renderPendingPanel(recentPending(expenses), pendingAll.length) +
    renderCategoriesPanel(cats, budgets) +
    "</div>" +
    sec("Recent claims") +
    renderRecentPanel(recentClaims(expenses)) +
    renderActions(hasBudget)
  );
}

// Staggered fade-up reveal + bar draw, honouring prefers-reduced-motion.
function animate(): void {
  const body = document.getElementById("body");
  if (!body) return;
  if (!REDUCED_MOTION) {
    for (let i = 0; i < body.children.length; i++) {
      const el = body.children[i] as HTMLElement;
      el.classList.add("reveal");
      el.style.animationDelay = Math.min(i + 1, 8) * 60 + "ms";
    }
  }
  requestAnimationFrame(() => {
    requestAnimationFrame(() => {
      document.querySelectorAll<HTMLElement>(".bar-fill").forEach((el) => {
        el.style.width = (el.getAttribute("data-pct") || "0") + "%";
      });
    });
  });
}

function wireBodyActions(expenseFormId: string, budgetFormId: string | null): void {
  const body = document.getElementById("body");
  if (!body) return;
  body.querySelectorAll("[data-action]").forEach((el) => {
    el.addEventListener("click", () => {
      const action = el.getAttribute("data-action");
      if (action === "new-expense") {
        FL.navigate(expenseFormId);
      } else if (action === "budgets" && budgetFormId) {
        FL.navigate(budgetFormId);
      } else if (action === "all-claims") {
        FL.navigate("form/" + expenseFormId + "/responses");
      } else if (action === "refresh") {
        void refresh(expenseFormId, budgetFormId);
      }
    });
  });
}

async function refresh(expenseFormId: string, budgetFormId: string | null): Promise<void> {
  let records: RawRecord[] = [];
  let budgetRecords: RawRecord[] = [];
  try {
    const results = await Promise.all([
      FL.records(expenseFormId, { limit: 500 }),
      budgetFormId
        ? FL.records(budgetFormId, { limit: 100 }).catch(() => [] as RawRecord[])
        : Promise.resolve([] as RawRecord[]),
    ]);
    records = results[0];
    budgetRecords = results[1];
  } catch (err) {
    setBody(renderError("Could not load expenses. Please try again."));
    FL.toast.error("Failed to load expenses");
    return;
  }
  const expenses: Expense[] = records.map(toExpense);
  const briefEl = document.getElementById("brief");
  if (briefEl) briefEl.innerHTML = renderBriefing(expenses, categoryBreakdown(expenses));
  setBody(renderDashboard(expenses, budgetFormId !== null, toBudgetMap(budgetRecords)));
  wireBodyActions(expenseFormId, budgetFormId);
  animate();
}

async function main(): Promise<void> {
  const root = document.getElementById("app");
  if (!root) return;
  root.innerHTML = renderShell();

  let ctx: AppContext;
  try {
    ctx = await FL.context();
  } catch (err) {
    setBody(renderError("Could not connect to this app."));
    return;
  }

  // Session warm-up; the header is intentionally impersonal (Briefing carries the facts).
  await FL.currentUser().catch(() => null);
  setHeader(ctx.appName);

  const expenseForm = ctx.forms.find(
    (f) => (f.displayName || "").trim().toLowerCase() === "expense"
  );
  const budgetForm = ctx.forms.find(
    (f) => (f.displayName || "").trim().toLowerCase() === "category budget"
  );

  if (!expenseForm) {
    setBody(renderError("The 'Expense' form was not found in this app."));
    return;
  }

  const budgetId = budgetForm ? budgetForm.formId : null;

  const topNew = document.getElementById("top-new");
  if (topNew) {
    topNew.addEventListener("click", () => FL.navigate(expenseForm.formId));
  }

  await refresh(expenseForm.formId, budgetId);
}

main().catch(() => {
  const root = document.getElementById("app");
  if (root) {
    root.innerHTML =
      '<div class="wrap"><div class="load">The dashboard could not be loaded.</div></div>';
  }
});

// data.ts — pure data helpers for the Expenses dashboard.
// Imported by index.ts with a relative path to prove multi-file bundling.

export type StatusKey = "pending" | "approved" | "rejected";

export interface RawRecord {
  id: string;
  answers: Record<string, unknown>;
  submittedAt: string;
}

export interface Expense {
  id: string;
  description: string;
  amount: number;
  category: string;
  status: StatusKey;
  submittedBy: string;
  date: string;
  submittedAt: string;
}

export interface StatusTotals {
  count: number;
  amount: number;
}

export interface CategorySpend {
  category: string;
  amount: number;
  count: number;
}

// Choice/text values can arrive in a few shapes; normalise defensively.
export function normalizeStatus(raw: unknown): StatusKey {
  const s = String(raw ?? "").toLowerCase();
  if (s.includes("approve")) return "approved";
  if (s.includes("reject")) return "rejected";
  return "pending";
}

export function toNumber(raw: unknown): number {
  if (typeof raw === "number") return Number.isFinite(raw) ? raw : 0;
  const n = parseFloat(String(raw ?? "").replace(/[^0-9.\-]/g, ""));
  return Number.isFinite(n) ? n : 0;
}

export function prettify(raw: unknown): string {
  const s = String(raw ?? "").trim();
  if (!s) return "Uncategorized";
  return s.replace(/[_\-]+/g, " ").replace(/\b\w/g, (c) => c.toUpperCase());
}

// Whole-dollar display; tabular numerals are applied in CSS.
export function fmtMoney(n: number): string {
  return "$" + Math.round(n).toLocaleString("en-US");
}

export function fmtMoneyCompact(n: number): string {
  const x = Math.abs(n);
  if (x >= 1000000) return "$" + (n / 1000000).toFixed(1).replace(/\.0$/, "") + "M";
  if (x >= 10000) return "$" + Math.round(n / 1000) + "k";
  return fmtMoney(n);
}

export function toExpense(rec: RawRecord): Expense {
  const a = rec.answers || {};
  return {
    id: rec.id,
    description: String(a.description ?? ""),
    amount: toNumber(a.amount),
    category: prettify(a.category),
    status: normalizeStatus(a.status),
    submittedBy: String(a.submitted_by ?? ""),
    date: String(a.date ?? ""),
    submittedAt: rec.submittedAt,
  };
}

export function aggregate(expenses: Expense[]): Record<StatusKey, StatusTotals> {
  const base: Record<StatusKey, StatusTotals> = {
    pending: { count: 0, amount: 0 },
    approved: { count: 0, amount: 0 },
    rejected: { count: 0, amount: 0 },
  };
  for (const e of expenses) {
    base[e.status].count += 1;
    base[e.status].amount += e.amount;
  }
  return base;
}

// Spend excludes rejected expenses (money that will not be paid out).
export function categoryBreakdown(expenses: Expense[]): CategorySpend[] {
  const map = new Map<string, CategorySpend>();
  for (const e of expenses) {
    if (e.status === "rejected") continue;
    const cur = map.get(e.category) ?? { category: e.category, amount: 0, count: 0 };
    cur.amount += e.amount;
    cur.count += 1;
    map.set(e.category, cur);
  }
  return [...map.values()].sort((a, b) => b.amount - a.amount);
}

export function recentPending(expenses: Expense[], limit = 8): Expense[] {
  return expenses
    .filter((e) => e.status === "pending")
    .sort((a, b) => (b.submittedAt || "").localeCompare(a.submittedAt || ""))
    .slice(0, limit);
}

export function recentClaims(expenses: Expense[], limit = 6): Expense[] {
  return [...expenses]
    .sort((a, b) => (b.submittedAt || "").localeCompare(a.submittedAt || ""))
    .slice(0, limit);
}

function parseDate(s: string): Date | null {
  if (!s) return null;
  const d = new Date(s);
  return isNaN(d.getTime()) ? null : d;
}

// The expense date drives time buckets; fall back to the submission time.
function effectiveDate(e: Expense): Date | null {
  return parseDate(e.date) ?? parseDate(e.submittedAt);
}

export function inCurrentMonth(e: Expense): boolean {
  // Rolling 30-day window — a calendar month reads "$0 this month" on the 1st/2nd.
  const d = parseDate(e.date || e.submittedAt);
  if (!d) return false;
  const age = Date.now() - d.getTime();
  return age >= -86400000 && age <= 30 * 86400000;
}

// Committed spend for a set of claims (rejected money is never paid out).
export function spendOf(expenses: Expense[]): number {
  return expenses.reduce((sum, e) => (e.status === "rejected" ? sum : sum + e.amount), 0);
}

// Weekly spend buckets, oldest to newest, for the hero sparkline.
export function weeklySpend(expenses: Expense[], weeks = 8): number[] {
  const out: number[] = new Array(weeks).fill(0);
  const now = Date.now();
  for (const e of expenses) {
    if (e.status === "rejected") continue;
    const d = effectiveDate(e);
    if (!d) continue;
    const wk = Math.floor((now - d.getTime()) / 604800000);
    if (wk >= 0 && wk < weeks) out[weeks - 1 - wk] += e.amount;
  }
  return out;
}

export function ageLabel(e: Expense): string {
  const d = effectiveDate(e);
  if (!d) return "";
  const start = new Date();
  start.setHours(0, 0, 0, 0);
  const day = new Date(d.getFullYear(), d.getMonth(), d.getDate()).getTime();
  const diff = Math.round((day - start.getTime()) / 86400000);
  if (diff === 0) return "today";
  if (diff < 0) return -diff + "d ago";
  return "in " + diff + "d";
}

export function fmtShortDate(s: string): string {
  const d = parseDate(s);
  return d ? d.toLocaleDateString(undefined, { month: "short", day: "numeric" }) : "";
}

// Category Budget records: prettified category name to monthly limit.
export function toBudgetMap(records: RawRecord[]): Map<string, number> {
  const m = new Map<string, number>();
  for (const r of records) {
    const a = r.answers || {};
    const limit = toNumber(a.monthly_limit);
    if (limit > 0) m.set(prettify(a.category), limit);
  }
  return m;
}

export function topCategory(cats: CategorySpend[]): string {
  return cats.length ? cats[0].category : "";
}
